package dev.docweave.validation;

import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Replays vectors frozen from the retired Python scorers against their JVM replacements.
 *
 * <p>The vectors were generated by {@code generate-parity-vectors.py.txt} (retained beside the migration
 * evidence) from owned synthetic inputs only. Typed compact JSON comparison makes Python integer/float
 * distinctions, key order and failure paths part of the parity contract; no Python process runs here.
 */
class PythonScorerParityTest {
    /** Frozen vector file. */
    private static final Path VECTORS =
            Path.of("docweave-validation/src/test/resources/python-scorer-parity-vectors.json");
    /** Pinned vector identity, recorded in the migration evidence. */
    private static final String VECTORS_SHA256 = "79c9842d7e979d38f764062cd7df074eb5188363ae2415c504a41202d325f37d";
    /** Parsed vectors. */
    private static Map<String, Object> vectors;

    /** Creates the parity controls. */
    PythonScorerParityTest() {
    }

    /**
     * Loads and pins the vectors.
     *
     * @throws IOException if the resource cannot be read
     */
    @BeforeAll
    static void load() throws IOException {
        assertEquals(VECTORS_SHA256, ScoringFiles.sha256(VECTORS));
        vectors = PythonJson.object(PythonJson.parse(Files.readString(VECTORS)), "vectors");
    }

    /**
     * Returns one vector list.
     *
     * @param name vector group
     * @return entries
     */
    private static List<List<Object>> group(final String name) {
        return PythonJson.array(vectors.get(name), name).stream().map(item -> PythonJson.array(item, name)).toList();
    }

    /**
     * Converts a JSON number list into a box.
     *
     * @param value four numbers
     * @return box
     */
    private static TableGeometry.Box box(final Object value) {
        final var numbers = PythonJson.array(value, "box");
        return new TableGeometry.Box(((Number) numbers.get(0)).doubleValue(), ((Number) numbers.get(1)).doubleValue(),
                ((Number) numbers.get(2)).doubleValue(), ((Number) numbers.get(3)).doubleValue());
    }

    /**
     * Converts serialized tables back to geometry records.
     *
     * @param value list of table objects with sorted anchor lists
     * @return tables
     */
    private static List<TableGeometry.Table> tables(final Object value) {
        final var result = new ArrayList<TableGeometry.Table>();
        for (final Object item : PythonJson.array(value, "tables")) {
            final var table = PythonJson.object(item, "table");
            final var anchors = new LinkedHashSet<TableGeometry.SpanKey>();
            for (final Object anchor : PythonJson.array(table.get("anchors"), "anchors")) {
                final var key = PythonJson.array(anchor, "anchor");
                anchors.add(new TableGeometry.SpanKey(PythonJson.integerValue(key.get(0), "row"),
                        PythonJson.integerValue(key.get(1), "column"), PythonJson.integerValue(key.get(2), "row_span"),
                        PythonJson.integerValue(key.get(3), "column_span")));
            }
            result.add(new TableGeometry.Table((String) table.get("profile"), 0, 0,
                    PythonJson.integerValue(table.get("rows"), "rows"),
                    PythonJson.integerValue(table.get("columns"), "columns"), anchors, box(table.get("box"))));
        }
        return result;
    }

    /**
     * Asserts that an expected Python outcome (value or error) matches a JVM computation.
     *
     * @param expected {@code {"value": ...}} or {@code {"error": type, "message": text}}
     * @param computation JVM computation
     * @param label vector label
     */
    private static void assertOutcome(
            final Object expected, final java.util.concurrent.Callable<Object> computation, final String label) {
        final var outcome = PythonJson.object(expected, "outcome");
        if (outcome.containsKey("value")) {
            final Object actual;
            try {
                actual = computation.call();
            } catch (final Exception failure) {
                throw new AssertionError(label + " unexpectedly failed", failure);
            }
            assertEquals(PythonJson.compact(outcome.get("value")), PythonJson.compact(actual), label);
            return;
        }
        final var failure = assertThrows(Exception.class, computation::call, label);
        if ("ValueError".equals(outcome.get("error"))) {
            assertInstanceOf(IllegalArgumentException.class, failure, label);
            assertEquals(outcome.get("message"), failure.getMessage(), label);
        }
    }

    @Test
    void floatReprRoundingAndJsonLayoutMatchPython() {
        int floats = 0;
        for (final var entry : group("float_repr")) {
            assertEquals(entry.get(1), PythonJson.repr((Number) entry.get(0)), "repr " + floats++);
        }
        for (final var entry : group("round6")) {
            assertEquals(
                    PythonJson.compact(entry.get(1)), PythonJson.compact(PythonJson.round((Number) entry.get(0), 6)));
        }
        for (final Object item : PythonJson.array(vectors.get("dumps"), "dumps")) {
            final var entry = PythonJson.object(item, "dumps");
            assertEquals(entry.get("indent"), PythonJson.dumps(entry.get("value"), false));
            assertEquals(entry.get("sorted"), PythonJson.dumps(entry.get("value"), true));
            assertEquals(entry.get("compact"), PythonJson.compact(entry.get("value")));
        }
        assertTrue(floats > 2000);
        assertEquals("NaN", PythonJson.repr(Double.NaN));
        assertEquals("-Infinity", PythonJson.repr(Double.NEGATIVE_INFINITY));
        assertEquals(0L, PythonJson.round(0L, 6));
    }

    @Test
    void csvAndTsvRecordsMatchPythonReaders() {
        for (final var entry : group("csv")) {
            assertEquals(PythonJson.compact(entry.get(1)),
                    PythonJson.compact(ScoringFiles.records((String) entry.get(0), ',')), (String) entry.get(0));
        }
        for (final var entry : group("tsv")) {
            final var records = ScoringFiles.records(ScoringFiles.universalNewlines((String) entry.get(0)), '\t');
            final var header = records.getFirst();
            final var rows = new ArrayList<Object>();
            for (final var record : records.subList(1, records.size())) {
                if (record.isEmpty()) {
                    continue;
                }
                final var row = new java.util.LinkedHashMap<String, Object>();
                for (int column = 0; column < header.size(); column++) {
                    row.put(header.get(column), column < record.size() ? record.get(column) : null);
                }
                rows.add(row);
            }
            assertEquals(PythonJson.compact(entry.get(1)), PythonJson.compact(rows));
        }
        assertThrows(IllegalArgumentException.class, () -> ScoringFiles.records("\"open", ','));
    }

    @Test
    void envelopeAssociationMatchesPythonIncludingIntegerZeroResults() {
        for (final var entry : group("iou")) {
            assertEquals(PythonJson.compact(entry.get(2)),
                    PythonJson.compact(TableGeometry.iou(box(entry.get(0)), box(entry.get(1)))));
        }
        for (final var entry : group("business_iou")) {
            assertEquals(PythonJson.compact(entry.get(2)),
                    PythonJson.compact(BusinessCellTextScorer.iou(box(entry.get(0)), box(entry.get(1)))));
        }
        int matched = 0;
        for (final var entry : group("maximum_matches")) {
            final var references =
                    PythonJson.array(entry.get(0), "references").stream().map(PythonScorerParityTest::box).toList();
            final var candidates =
                    PythonJson.array(entry.get(1), "candidates").stream().map(PythonScorerParityTest::box).toList();
            final var pairs =
                    TableGeometry.maximumMatches(references, candidates, 0.5)
                            .stream()
                            .map(match -> (Object) List.of((long) match.reference(), (long) match.candidate()))
                            .toList();
            matched += pairs.size();
            assertEquals(PythonJson.compact(entry.get(2)), PythonJson.compact(pairs));
            assertEquals(PythonJson.compact(entry.get(3)),
                    PythonJson.compact(StructureMetrics.proposals(references, candidates)));
        }
        assertTrue(matched > 200, "Vectors must exercise contested one-to-one matches");
        for (final var entry : group("structure_metric")) {
            assertEquals(PythonJson.compact(entry.get(2)),
                    PythonJson.compact(StructureMetrics.structure(tables(entry.get(0)), tables(entry.get(1)))));
        }
    }

    @Test
    void compactInteriorsMatchPythonIncludingRejectedPredictions() {
        int rejected = 0;
        for (final var entry : group("interior")) {
            final var expected = PythonJson.object(entry.get(1), "outcome");
            rejected += expected.containsKey("error") ? 1 : 0;
            assertOutcome(expected, () -> {
                final long[] interior = CompactLayoutScorer.interior(box(entry.get(0)));
                return List.of(interior[0], interior[1], interior[2], interior[3]);
            }, "interior " + entry.get(0));
        }
        assertTrue(rejected > 10);
    }

    @Test
    void businessTextProjectionSelectionAndComparisonMatchPython() {
        for (final var entry : group("normalize")) {
            assertEquals(entry.get(1), BusinessCellTextScorer.normalize((String) entry.get(0)));
        }
        for (final var entry : group("cells")) {
            assertOutcome(
                    entry.get(1), () -> BusinessCellTextScorer.cells((String) entry.get(0)), (String) entry.get(0));
        }
        for (final var entry : group("select")) {
            final var tables = PythonJson.array(entry.get(0), "tables")
                                       .stream()
                                       .map(table -> PythonJson.object(table, "table"))
                                       .toList();
            final var selection = BusinessCellTextScorer.select(tables, box(entry.get(1)));
            assertEquals(PythonJson.compact(entry.get(2)),
                    PythonJson.compact(selection.table() == null ? null : selection.table().get("id")));
            assertEquals(PythonJson.compact(entry.get(3)), PythonJson.compact(selection.overlap()));
            assertEquals(
                    PythonJson.compact(entry.get(4)), PythonJson.compact(PythonJson.round(selection.overlap(), 6)));
        }
        int failures = 0;
        for (final var entry : group("compare")) {
            final List<List<String>> reference =
                    PythonJson.array(entry.get(0), "reference")
                            .stream()
                            .map(row -> PythonJson.array(row, "row").stream().map(String.class ::cast).toList())
                            .toList();
            final var prediction = entry.get(1) == null ? null : PythonJson.object(entry.get(1), "prediction");
            failures += PythonJson.object(entry.get(2), "outcome").containsKey("error") ? 1 : 0;
            assertOutcome(entry.get(2), () -> BusinessCellTextScorer.compare(reference, prediction), "compare");
        }
        assertTrue(failures > 10, "Vectors must exercise rejected projections");
    }
}
